import {build} from 'esbuild';
import {mkdir,readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
const root=fileURLToPath(new URL('../',import.meta.url));
const directory=resolve(root,'public/vendor/prism-1.30.0');
const license=await readFile(resolve(root,'node_modules/prismjs/LICENSE'),'utf8');
const result=await build({absWorkingDir:root,entryPoints:['src/ui/syntax-worker.cjs'],bundle:true,write:false,
  format:'iife',platform:'browser',target:'es2022',minify:true,legalComments:'inline',
  banner:{js:'// Prism 1.30.0. Generated by scripts/syntax-bundle.mjs.\n/*\n'+license.trim()+'\n*/'},logLevel:'silent'});
const files=[['syntax-worker.js',result.outputFiles[0].text],['LICENSE.txt',license]];
if(process.argv.includes('--write'))await mkdir(directory,{recursive:true});
for(const [name,text] of files){
  const path=resolve(directory,name);
  if(process.argv.includes('--write'))await writeFile(path,text);
  else if(await readFile(path,'utf8')!==text)throw Error('Syntax bundle changed; review and run scripts/syntax-bundle.mjs --write.');
}
console.log(`Local syntax worker verified: ${Buffer.byteLength(result.outputFiles[0].text)} bytes.`);
